import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Verknüpfungen zu Home-Assistant-Seiten und externen Webseiten erstellen.","frontmatter":{"title":"Eigene Seitenleisten-Verknüpfungen","description":"UIX-Verknüpfungen zu Home-Assistant-Seiten und externen Webseiten erstellen."},"headers":[],"relativePath":"projects/uix/extras/custom-sidebar-panels.md","filePath":"projects/uix/extras/custom-sidebar-panels.md","lastUpdated":1793871680000}'),s={name:"projects/uix/extras/custom-sidebar-panels.md"};function a(o,e,l,d,u,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="eigene-seitenleisten-verknupfungen" tabindex="-1">Eigene Seitenleisten-Verknüpfungen <a class="header-anchor" href="#eigene-seitenleisten-verknupfungen" aria-label="Permalink to &quot;Eigene Seitenleisten-Verknüpfungen&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Vorschaufunktionen</p><p>Interne Seitenleisten-Verknüpfungen sind ab <strong>9.0.0-beta.6</strong> verfügbar. Externe Ziele und <strong>Open in new tab</strong> kommen mit <strong>9.0.0-beta.8</strong> hinzu und benötigen <strong>Home Assistant 2026.11.0b0 oder neuer</strong>. Geprüfte Quelle: <a href="https://github.com/Lint-Free-Technology/uix/commit/e4a1caa6437f88282cfe04d768d3c11df387fc42" target="_blank" rel="noreferrer">e4a1caa</a>, 02.11.2026. Die stabile Basis bleibt UIX 8.4.0.</p></div><p>UIX kann eigene Einträge in der Home-Assistant-Seitenleiste hinzufügen, die eine andere Home-Assistant-Seite oder eine Webseite öffnen. Das erleichtert den Zugriff auf häufig verwendete Seiten unter „Einstellungen“ und auf zugehörige Webdienste.</p><p>Öffne <strong>Einstellungen → Geräte &amp; Dienste → UI eXtension → Konfigurieren</strong> und wähle <strong>Manage custom sidebar panels</strong>. Wähle das Icon und gib Titel und Ziel ein.</p><p>Aktiviere <strong>Admin required</strong>, um den Eintrag auf Administratorkonten zu beschränken.</p><p>Als Ziel sind Home-Assistant-Pfade mit führendem <code>/</code>, etwa <code>/config/dashboard</code>, oder absolute <code>http</code>- und <code>https</code>-URLs erlaubt. Andere URL-Schemata werden nicht akzeptiert.</p><p>Mit <strong>Open in new tab</strong> öffnet sich das Ziel in einem neuen Tab. Der bisherige Home-Assistant-Tab kehrt zur zuvor angezeigten Seite zurück. Blockiert der Browser den neuen Tab, öffnet UIX das Ziel stattdessen im aktuellen Tab. Ohne diese Option öffnen externe Webseiten im aktuellen Tab; Home-Assistant-Pfade verwenden weiterhin die Navigation innerhalb der Anwendung.</p><div class="info custom-block"><p class="custom-block-title">Neuer Tab und Popup-Sperre</p><p>Ob ein neuer Tab geöffnet werden darf, entscheidet die Popup-Sperre des Browsers. UIX versucht dies bei Auswahl des Seitenleisteneintrags, kann es aber nicht garantieren. Bei einer Blockierung wird das Ziel im aktuellen Tab geöffnet.</p></div><p>Jeder Eintrag erhält eine feste interne URL, die UIX verwaltet. Titel, Icon und Ziel lassen sich deshalb ändern, ohne den Eintrag neu anzulegen. Löschen entfernt ihn sofort aus der Seitenleiste.</p><div class="tip custom-block"><p class="custom-block-title">Reihenfolge der Seitenleiste</p><p>Jeder Benutzer kann Einträge über sein Profil <a href="https://www.home-assistant.io/dashboards/dashboards/#reorganizing-items-in-the-sidebar" target="_blank" rel="noreferrer">sortieren und ausblenden</a>.</p></div><div class="info custom-block"><p class="custom-block-title">Weiterleitung</p><p>Ein eigenes Panel ist eine Weiterleitung, keine zweite Kopie der Zielseite und kein iframe. Bei internen Zielen ersetzt UIX die Panel-URL durch das konfigurierte Ziel. Dadurch entsteht im Browserverlauf kein zusätzlicher Weiterleitungsschritt.</p></div><p>Quelle: <a href="https://uix.lf.technology/extras/custom-sidebar-panels/" target="_blank" rel="noreferrer">englische UIX-Originaldokumentation</a>, Lint-Free-Technology/uix, <a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="noreferrer">CC BY 4.0</a>.</p>',12)])])}const f=n(s,[["render",a]]);export{p as __pageData,f as default};
